* AULA-C CC0-1.0; modelo simplificado
.subckt UPIITA_POT10K A W B params: R=10000 POS=0.5
R1 A W {R*max(0,min(1,POS))+1m}
R2 W B {R*(1-max(0,min(1,POS)))+1m}
.ends UPIITA_POT10K

* AULA-C CC0-1.0; macromodelo propio de _TL082: un polo (GBW), slew rate y salida a 1.5 V de los rieles
.subckt UPIITA_TL082 OUT1 INM1 INP1 VEE INP2 INM2 OUT2 VCC params: GBW=3meg SR=13meg AOL=200k
.param CINT=1n ISR={SR*CINT} GM={6.2832*GBW*CINT}
BMID MID 0 V={(V(VCC)+V(VEE))/2}
BHI HI 0 V={max(V(VCC)-1.5,V(MID))}
BLO LO 0 V={min(V(VEE)+1.5,V(MID))}
RQ VCC VEE 10.7k
RIN1 INP1 INM1 1e12
BG1 MID N1 I={max(-ISR,min(ISR,GM*V(INP1,INM1)))}
CI1 N1 MID {CINT}
RO1 N1 MID {AOL/GM}
DH1 N1 HI DCLAMP
DL1 LO N1 DCLAMP
BO1 OI1 0 V={V(N1)}
ROUT1 OI1 OUT1 75
RIN2 INP2 INM2 1e12
BG2 MID N2 I={max(-ISR,min(ISR,GM*V(INP2,INM2)))}
CI2 N2 MID {CINT}
RO2 N2 MID {AOL/GM}
DH2 N2 HI DCLAMP
DL2 LO N2 DCLAMP
BO2 OI2 0 V={V(N2)}
ROUT2 OI2 OUT2 75
.model DCLAMP D(IS=1e-15 N=0.1)
.ends UPIITA_TL082

